SourceCode.Declaration:
/// <summary>
/// Contract class for generating a dialog fields/parameters used for batch execution to Update Stock availability details for the replenishment sites fetching information from the related parent site.
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessing(classStr(METUpdateStockAvailabilityUIBuilder))
]
internal final class METUpdateStockAvailabilityContract implements SysOperationValidatable
{
    private ItemId itemId;
    private InventSiteId siteId;
    private METStockAvailDate stockAvailabilityDate;
    private EcoResProductLifecycleStateId productLifeCycleStateId;
    private boolean periodicExecution;

}

Method.Source:
/// <summary>
/// Get/Set Site parameter.
/// </summary>
/// <param name = "_siteId">InventSiteId</param>
/// <returns>InventSiteId always, as parameters cannot be blank or invalid Site value</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@SYS103211"))
]
public InventSiteId parmInventSiteId(InventSiteId _siteId = siteId)
{
    siteId = _siteId;
    return siteId;
}

/// <summary>
/// Get/Set Item number parameter.
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns>ItemId always, as parameters cannot be blank or invalid Item number value</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@MET:ItemNumber"))
]
public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

/// <summary>
/// Get/Set Stock availability date.
/// </summary>
/// <param name = "_stockAvailabilityDate">Date value</param>
/// <returns>Date value, could be blank or set with a valid date</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@MET:METStockAvailDate"))
]
public METStockAvailDate parmMETStockAvailDate(METStockAvailDate _stockAvailabilityDate = stockAvailabilityDate)
{
    stockAvailabilityDate = _stockAvailabilityDate;
    return stockAvailabilityDate;
}

/// <summary>
/// Get/Set Product lifecycle state parameter.
/// </summary>
/// <param name = "_productLifeCycleStateId">Product lifecycle state</param>
/// <returns>Product lifecycle state</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@SCM:EcoResProductLifecycleState"))
]
public EcoResProductLifecycleStateId parmProductLifecycleStateId(EcoResProductLifecycleStateId _productLifeCycleStateId = productLifeCycleStateId)
{
    productLifeCycleStateId = _productLifeCycleStateId;
    return productLifeCycleStateId;
}

/// <summary>
/// Boolean method to determine execution is periodic or run for default order setting of Item.
/// </summary>
/// <param name = "_periodicExecution">Boolean value</param>
/// <returns>True for periodic execution, False when run for Default order setting of item </returns>
public boolean parmIsPeriodicExecution(boolean _periodicExecution = periodicExecution)
{
    periodicExecution = _periodicExecution;
    return periodicExecution;
}

/// <summary>
/// Method to intialise the contract values required in process for updating stock availability.
/// </summary>
/// <param name = "_args">Args type holding the callers data</param>
public void initFromArgs(Args _args)
{
    if (_args
        && _args.record()
        && _args.dataset() == tableNum(InventItemPurchSetup))
    {
        InventItemPurchSetup inventItemPurchSetup = _args.record();
        InventDim inventDim = InventDim::find(inventItemPurchSetup.InventDimId);
        this.parmInventSiteId(inventDim.InventSiteId); //inventItemPurchSetup.inventSiteId() - returned 'AllBlank' value.
        this.parmItemId(inventItemPurchSetup.ItemId);
        this.parmIsPeriodicExecution(false);
    }
    else
    {
        this.parmIsPeriodicExecution(true);
    }
}

/// <summary>
/// This implementation of the interface validates the values of the contract parameters.
/// </summary>
/// <returns>Boolean True, upon successful validation checks, otherwise false</returns>
public boolean validate()
{
    boolean ret = true;

    if (!itemId)
    {
        ret = checkFailed("@MET:ItemNumberCannotBeBlank");
    }

    if (!siteId)
    {
        ret = checkFailed("@MET:SiteCannnotBeBlank");
    }

    if (METVendParameters::find().UpdateFromParentToTransferSites == NoYes::No)
    {
        ret = checkfailed("@MET:UpdateFromParentToTransferSitesParameterNoSet");
    }

    return ret;
}
